`timescale 1ns / 1ps

module trigram(
    input wire clk,
    input wire reset,
    input wire in_valid,
    input wire [7:0] in_byte,
    output reg tri_valid,
    output reg [7:0] b0, 
    output reg [7:0] b1, 
    output reg [7:0] b2,
    output wire [10:0] bucket
);
    
    `include "hw/model_params.vh"
    wire is_punct;
    wire [7:0] norm_byte;
    reg [2:0] count;

    // Calls the h3 function auto generated by export.py
    assign bucket = h3({b0, b1, b2});

    assign is_punct = ((8'h21 <= in_byte && in_byte <= 8'h2F) || 
                        ((8'h3A <= in_byte && in_byte <= 8'h40)) || 
                        ((8'h5B <= in_byte && in_byte <= 8'h60)) || 
                        (8'h7B <= in_byte && in_byte <= 8'h7E));
    // Combinational logic for capital letters
    assign norm_byte = (8'h41 <= in_byte && in_byte <= 8'h5A) ? in_byte | 8'h20 : in_byte;

    always @(posedge clk) begin
        if (reset) begin
            count <= 3'd0;
            tri_valid <= 1'b0;
        end
        else begin
            tri_valid <= 1'b0;

            if (in_valid && !is_punct) begin
                b2 <= norm_byte;
                b1 <= b2;
                b0 <= b1;
                if (count < 3'd2) begin
                    count <= count + 1;
                end
                if (count == 3'd2) begin
                    tri_valid <= 1'b1;
                end
            end
        end
    end

endmodule